{
  "name": "FirebaseCoreExtension",
  "version": "12.19.0",
  "summary": "Extended FirebaseCore APIs for Firebase product SDKs",
  "description": "Not for public use.\nCommon FirebaseCore APIs for use in Firebase product SDKs.\nWhen depending on `FirebaseCoreExtension`, also depend on `FirebaseCore` to\navoid potential linker issues.",
  "homepage": "https://firebase.google.com",
  "license": {
    "type": "Apache-2.0",
    "file": "LICENSE"
  },
  "authors": "Google, Inc.",
  "source": {
    "git": "https://github.com/firebase/firebase-ios-sdk.git",
    "tag": "CocoaPods-12.19.0"
  },
  "social_media_url": "https://twitter.com/Firebase",
  "swift_versions": "5.9",
  "platforms": {
    "ios": "15.0",
    "osx": "10.15",
    "tvos": "15.0",
    "watchos": "7.0"
  },
  "source_files": "FirebaseCore/Extension/*.[hm]",
  "public_header_files": "FirebaseCore/Extension/*.h",
  "resource_bundles": {
    "FirebaseCoreExtension_Privacy": "FirebaseCore/Extension/Resources/PrivacyInfo.xcprivacy"
  },
  "pod_target_xcconfig": {
    "DEFINES_MODULE": "YES"
  },
  "dependencies": {
    "FirebaseCore": [
      "~> 12.19.0"
    ]
  },
  "swift_version": "5.9"
}
